# server-stop.ps1 - stop Mainframe server
# AUTO-GENERATED by Tools/gen_launchers.py. Do not edit by hand.
# Regenerate: python Tools/gen_launchers.py
$ErrorActionPreference = "Continue"
$Root = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$CfgFile = Join-Path $Root "config.json"
if (-not (Test-Path $CfgFile)) { Write-Host "config.json not found: $CfgFile" -ForegroundColor Red; exit 1 }
$Cfg = Get-Content $CfgFile -Raw | ConvertFrom-Json
$env:JEWAI_CONFIG = $CfgFile
function Log($m) { Write-Host ("[" + (Get-Date -Format "HH:mm:ss") + "] " + $m) }

$port = 8670
$proc = Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue | Select-Object -ExpandProperty OwningProcess
if ($proc) { Stop-Process -Id $proc -Force -ErrorAction SilentlyContinue; Log "mainframe stopped" } else { Log "mainframe not running" }
